	if _, err := s.Destroy("APP1", "2024-12-30", "A001"); !errors.Is(err, ErrNotExpired) {
		t.Fatalf("第一次销毁错误 = %v", err)
	}
	// 条件改变后用同一编号再次提交，成功。
	if _, err := s.Destroy("APP1", "2024-12-31", "A001"); err != nil {
		t.Fatalf("再次提交: %v", err)
	}
